"""
Response templates: the inverse of chat templates.

Where a chat template turns a list of message dicts into a single string of tokens ready for the model, a *response
template* turns the raw string generated by the model back into a structured message dict, with keys like ``role``,
``content``, ``thinking`` and ``tool_calls``. This lets user-facing code work with a universal message-dict API and
ignore the model-specific control tokens and formats.

The two public entry points are:

* [`parse_response`] - a one-shot function that parses a complete generation (or a batch of them).
* [`ResponseParser`] - a stateful, incremental parser for streaming, exposing ``feed`` / ``finalize`` and emitting
  ``region_open`` / ``region_chunk`` / ``region_close`` events as text arrives.

See the ``chat_response_parsing`` documentation for a full description of the template format.
"""

from __future__ import annotations

import copy
import json

import regex


# Content types whose captured text is already (modulo whitespace) the final value. Chunks for these regions are
# emitted with ``dirty=False`` while streaming, because each chunk is usable as-is.
_TEXT_TYPES = {"text", "int", "float", "bool"}
# All the content types we know how to parse.
_CONTENT_TYPES = _TEXT_TYPES | {"json", "xml-inline", "kv-lines"}
# The response template versions this implementation understands.
_SUPPORTED_VERSIONS = {1}

# A transform placeholder is a string that consists of exactly one ``{name}`` token. ``_PLACEHOLDER`` matches such a
# string in full, while ``_PLACEHOLDER_SEARCH`` detects a placeholder anywhere inside a larger string (which is an
# error - placeholders may not be mixed with surrounding text).
_PLACEHOLDER = regex.compile(r"\{([^{}]+)\}")
_PLACEHOLDER_SEARCH = regex.compile(r"\{[^{}]+\}")


def is_response_template(spec) -> bool:
    """Return ``True`` if ``spec`` looks like a new-style response template (as opposed to a legacy schema)."""
    return isinstance(spec, dict) and ("version" in spec or "fields" in spec)


