def _normalize_jsonish(text: str, unquoted_keys: bool, string_delims: list) -> str:
    """Turn almost-JSON output into valid JSON by quoting bare keys and normalizing custom string delimiters."""
    captured = []

    def _capture(match):
        captured.append(match.group(1))
        return f"\x00{len(captured) - 1}\x00"

    # Pull the contents of custom string delimiters out first, so their contents are not affected by key-quoting.
    for pair in string_delims:
        open_delim, close_delim = pair[0], pair[1]
        pattern = regex.escape(open_delim) + r"(.*?)" + regex.escape(close_delim)
        text = regex.sub(pattern, _capture, text, flags=regex.DOTALL)

    if unquoted_keys:
        # Quote bare object keys, i.e. a word that follows a ``{`` or ``,`` and precedes a ``:``.
        text = regex.sub(
            r"([{,]\s*)([A-Za-z_]\w*)(\s*:)",
            lambda m: f'{m.group(1)}"{m.group(2)}"{m.group(3)}',
            text,
            flags=regex.DOTALL,
        )

    # Reinsert the captured strings as valid JSON strings.
    for i, string in enumerate(captured):
        text = text.replace(f"\x00{i}\x00", json.dumps(string))

    return text


def _parse_json(text: str, args: dict):
    unquoted_keys = args.get("unquoted_keys", False)
    string_delims = args.get("string_delims", None) or []
    allow_non_json = args.get("allow_non_json", False)

    processed = text.strip()
    if unquoted_keys or string_delims:
        processed = _normalize_jsonish(processed, unquoted_keys, string_delims)

    try:
        return json.loads(processed)
    except json.JSONDecodeError as e:
        if allow_non_json:
            return text.strip()
        raise ValueError(f"Response template `json` parser could not parse content as JSON: {text!r}\nError: {e}")


def _parse_xml_inline(text: str, args: dict):
    tag_pattern = args.get("tag_pattern")
    if not tag_pattern:
        raise ValueError("The `xml-inline` content parser requires a `tag_pattern` in `content_args`.")
    value_parser = args.get("value_parser")
    merge_duplicates = args.get("merge_duplicates", False)

    compiled = regex.compile(tag_pattern, flags=regex.DOTALL)
    result = {}
    for match in compiled.finditer(text):
        groups = match.groupdict()
        if "key" not in groups or "value" not in groups:
            raise ValueError(
                f"The `xml-inline` `tag_pattern` must contain named groups `key` and `value`.\nPattern: {tag_pattern}"
            )
        key = groups["key"]
        value = groups["value"]
        if value_parser is not None:
            value = _parse_content(value, value_parser.get("name", "text"), value_parser.get("args", {}))
        if merge_duplicates and key in result:
            if not isinstance(result[key], list):
                result[key] = [result[key]]
            result[key].append(value)
        else:
            result[key] = value
    return result


def _parse_kv_lines(text: str, args: dict):
    line_sep = args.get("line_sep", "\n")
    kv_sep = args.get("kv_sep", ":")
    strip = args.get("strip", True)
    value_parser = args.get("value_parser")

    result = {}
    for line in text.split(line_sep):
        if kv_sep not in line:
            continue
        key, value = line.split(kv_sep, 1)
        if strip:
            key = key.strip()
            value = value.strip()
        if not key:
            continue
        if value_parser is not None:
            value = _parse_content(value, value_parser.get("name", "text"), value_parser.get("args", {}))
        result[key] = value
    return result


def _parse_content(text: str, content_type: str, args: dict):
    """Parse the raw captured text of a region into its final (pre-transform) value."""
    args = args or {}
    if content_type == "text":
        return text.strip() if args.get("strip", True) else text
    if content_type == "int":
        stripped = text.strip()
        try:
            return int(stripped)
        except ValueError:
            raise ValueError(f"Response template `int` parser could not parse content as an integer: {stripped!r}")
    if content_type == "float":
        stripped = text.strip()
        try:
            return float(stripped)
        except ValueError:
            raise ValueError(f"Response template `float` parser could not parse content as a float: {stripped!r}")
    if content_type == "bool":
        stripped = text.strip().lower()
        if stripped in ("true", "1"):
            return True

